'use client';
import * as React from 'react';
import { useUITheme } from 'uitheme-web/react';
import { cn } from './classes';
import { Toggle } from '@base-ui/react/toggle';
export const ThemeToggle = React.forwardRef(function ThemeToggle({ className, classes, label = 'Toggle appearance', disabled = false }, forwardedRef) {
    const { resolvedTheme, switchTheme, mounted } = useUITheme();
    const target = resolvedTheme === 'dark' ? 'light' : 'dark';
    return (<div className={cn('inline-flex', classes?.root, className)}>
      <Toggle ref={forwardedRef} type="button" aria-label={label} pressed={resolvedTheme === 'dark'} disabled={disabled || !mounted} className={cn('inline-flex items-center justify-center rounded-md border border-input bg-background px-3 py-2 text-sm font-medium text-foreground shadow-sm transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50', classes?.trigger)} onClick={(event) => void switchTheme(target, { element: event.currentTarget })}>
        {resolvedTheme === 'dark' ? 'Dark' : 'Light'}
      </Toggle>
    </div>);
});

import { twMerge } from 'tailwind-merge';
export function cn(...classes) {
    return twMerge(classes.filter(Boolean).join(' '));
}
